// CSD_RATIONALE_BEGIN
// Attempt 71: Replace RegenerateUnitOnGroundingFailure (RUGF) in Phase 3 with
// a direct ConstrainedStep loop.
//
// Diagnosis of attempt 66 (53.3% best) vs current approach:
// - 145/154 mode_A failures: syntax-valid SQL with WRONG STRUCTURE (wrong
//   aggregation, wrong JOIN direction, wrong subquery pattern). All identifiers
//   are correctly grounded in the schema.
// - RUGF's grounding check cannot help with structural errors — it only rolls
//   back when identifiers are not found in the prompt, which is not the dominant
//   failure mode.
// - RUGF adds overhead (dead-end-avoiding steps, rollback loops) that may
//   consume budget without fixing structural issues.
// - Repetition loops (paragraph example) are addressed by the 280-step budget
//   cap + early exit on IsCompletePrefix.
//
// New approach: pure ConstrainedStep loop in Phase 3.
// - Each step: hard-masked ConstrainedStep → AppendConstrainedToken
// - Early exit when parser.IsCompletePrefix or EOS
// - Budget 280 steps (covers complex Spider queries; median is 25 tokens)
// - Phase 4 unchanged: CloseConstrainedSpan or CloseSpanWithinBudget(120)
// - Guidance unchanged from attempt 65/66 (proven best guidance string)
//
// Budget ceiling: Phase1(5)+Phase2(1)+Phase3(280)+Phase4(120) = 406 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (UnconstrainedStep loop): Guard is !insideConstrainedOut so the
//   implication is vacuous throughout. The only true-flip is via
//   RenderedEndsWith(generated, "<<"), at which point currentConstrainedOut := []
//   and IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut false (vacuous).
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Postcondition: currentConstrainedOut := []; IsValidPrefix([]) holds.
//
// Phase 3 (ConstrainedStep loop): ConstrainedStep hard-masks to parser-valid
//   tokens plus EOS, so any non-EOS return is parser-valid for extension.
//   The IsTokenValidNext guard before AppendConstrainedToken further ensures
//   the extension is accepted by the parser. AppendConstrainedToken's
//   postcondition guarantees parser.IsValidPrefix(currentConstrainedOut) after
//   the append. On EOS or IsCompletePrefix exit, insideConstrainedOut is either
//   unchanged (still true, invariant holds by induction) or we've broken out
//   of the loop. No path sets insideConstrainedOut=false inside this loop.
//
// Phase 4a (CloseConstrainedSpan): Sets insideConstrainedOut := false and
//   currentConstrainedOut := [], making the implication vacuously true.
//
// Phase 4b (CloseSpanWithinBudget): Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep adds 1 to steps and 0 (EOS) or 1 (token)
//   to |generated|. So |generated| <= |generatedPrefix| + steps holds after
//   each iteration. The outer steps variable tracks total Phase 1 cost.
//
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token; steps += 1. 1:1.
//
// Phase 3: sqlSteps is the loop counter. Each iteration: ConstrainedStep
//   adds 1 to sqlSteps; AppendConstrainedToken adds at most 1 to |generated|
//   (0 on EOS branch). So |generated| <= |generatedPrefix| + steps + sqlSteps
//   is a valid loop invariant. After the loop: steps += sqlSteps <= 280.
//   sqlBudget = min(remaining-1, 280) ensures steps+sqlBudget <= maxSteps.
//   |currentConstrainedOut| <= |generated| is preserved since both grow by 1
//   per AppendConstrainedToken call.
//
// Phase 4a: CloseConstrainedSpan adds +1 step and at most 1 ">>" token. ≤1:1.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved transitively.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Pure ConstrainedStep loop for SQL generation
// Budget capped at 280 steps; early exit on complete parse or EOS.
// Replaces RUGF: mode_A failures are structural (wrong aggregation/JOIN),
// not identifier grounding failures. ConstrainedStep loop gives full grammar
// control without rollback overhead.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var sqlBudget: nat;
  if remaining <= 1 {
    sqlBudget := 0;
  } else if remaining - 1 <= 280 {
    sqlBudget := remaining - 1;
  } else {
    sqlBudget := 280;
  }

  var sqlSteps: nat := 0;
  while sqlSteps < sqlBudget && insideConstrainedOut
    invariant 0 <= sqlSteps <= sqlBudget
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps + sqlSteps
    decreases sqlBudget - sqlSteps
  {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      break;
    }
    if helpers.IsTokenValidNext(parser, currentConstrainedOut, next) {
      var og, oi, oc := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
    }
    if parser.IsCompletePrefix(currentConstrainedOut) {
      break;
    }
  }
  steps := steps + sqlSteps;
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

